DROP TABLE IF EXISTS `report_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `report_template` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `association` varchar(255) DEFAULT NULL,
  `level` int(11) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `root_concept_code` varchar(255) DEFAULT NULL,
  `sort_column` int(11) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `type` varchar(20) NOT NULL,
  `date_created` datetime NOT NULL,
  `date_last_updated` datetime NOT NULL,
  `created_by` varchar(20) NOT NULL,
  `last_updated_by` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_report_template_1` (`status`),
  KEY `fk_report_template_2` (`type`),
  KEY `fk_report_template_3` (`association`),
  CONSTRAINT `fk_report_template_1` FOREIGN KEY (`status`) REFERENCES `lk_report_template_status` (`name`),
  CONSTRAINT `fk_report_template_2` FOREIGN KEY (`type`) REFERENCES `lk_report_template_type` (`name`),
  CONSTRAINT `fk_report_template_3` FOREIGN KEY (`association`) REFERENCES `lk_association` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=182 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

