CREATE TABLE `report_template_column` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `column_number` int(11) NOT NULL,
  `label` varchar(255) NOT NULL,
  `display` varchar(100) NOT NULL,
  `property_type` varchar(100) NOT NULL,
  `property` varchar(255) DEFAULT NULL,
  `source` varchar(255) DEFAULT NULL,
  `source_group` varchar(255) DEFAULT NULL,
  `subsource` varchar(255) DEFAULT NULL,
  `report_template_id` int(11) NOT NULL,
  `date_created` datetime NOT NULL,
  `date_last_updated` datetime NOT NULL,
  `created_by` varchar(20) NOT NULL,
  `last_updated_by` varchar(20) NOT NULL,
  `attr` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_report_template_column_1` (`report_template_id`),
  KEY `fk_report_template_column_2` (`display`),
  KEY `fk_report_template_column_4` (`property`),
  KEY `fk_report_template_column_5` (`source`),
  KEY `fk_report_template_column_6` (`source_group`),
  KEY `fk_report_template_column_7` (`subsource`),
  CONSTRAINT `fk_report_template_column_1` FOREIGN KEY (`report_template_id`) REFERENCES `report_template` (`id`),
  CONSTRAINT `fk_report_template_column_2` FOREIGN KEY (`display`) REFERENCES `lk_display` (`name`),
  CONSTRAINT `fk_report_template_column_4` FOREIGN KEY (`property`) REFERENCES `lk_property` (`code`),
  CONSTRAINT `fk_report_template_column_5` FOREIGN KEY (`source`) REFERENCES `lk_source` (`name`),
  CONSTRAINT `fk_report_template_column_6` FOREIGN KEY (`source_group`) REFERENCES `lk_group` (`name`),
  CONSTRAINT `fk_report_template_column_7` FOREIGN KEY (`subsource`) REFERENCES `lk_subsource` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=7867 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

